#!/usr/bin/env node
/**
 * Syncs the PGlite migration SQL generated by core's migration-export
 * (scripts/core.just → build-wasm) into the console app's
 * data/core so the browser can bundle and replay them with PGlite.
 *
 * If the generated files are missing, it regenerates them via cargo first.
 */
import { execSync } from "node:child_process";
import {
  cpSync,
  mkdirSync,
  readdirSync,
  rmSync,
} from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const consoleDir = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const sourceDir = resolve(consoleDir, "../core/generated/pglite/migrations");
const destDir = resolve(consoleDir, "app/layers/shared/data/core/migrations");
const manifestPath = resolve(consoleDir, "../core/migration/Cargo.toml");

const hasSqlFiles = () => {
  try {
    return readdirSync(sourceDir).some((f) => f.endsWith(".sql"));
  } catch {
    return false;
  }
};

if (!hasSqlFiles()) {
  console.log("[core] generated migration SQL missing — running migration-export…");
  try {
    execSync(
      `cargo run --quiet --manifest-path "${manifestPath}" --bin migration-export -- "${sourceDir}" postgres`,
      { stdio: "inherit" },
    );
  } catch {
    console.error(
      "\n[core] could not generate migration SQL. Run `just build-wasm` (or `just schema-export`) from the repo root, then retry.",
    );
    process.exit(1);
  }
}

if (!hasSqlFiles()) {
  console.error(
    "\n[core] no migration SQL found in core/generated/pglite/migrations. Run `just build-wasm` from the repo root, then retry.",
  );
  process.exit(1);
}

const files = readdirSync(sourceDir)
  .filter((f) => f.endsWith(".sql"))
  .sort();

rmSync(destDir, { recursive: true, force: true });
mkdirSync(destDir, { recursive: true });

for (const file of files) {
  cpSync(join(sourceDir, file), join(destDir, file));
}

console.log(
  `[core] synced ${files.length} migration files → app/layers/shared/data/core/migrations`,
);
